318	/**
319	 * Full recount from the source tables. Called by the rollup job and by every
320	 * event that could have moved a counter — after recounting, the seat and
321	 * project totals are checked against the plan so a breach surfaces as an
322	 * event rather than waiting for the next write to be rejected.
323	 */
324	export async function recomputeUsage(
325	  orgId: OrgId,
326	): Promise<OrganizationUsage> {
327	  const usage = await usageRepo.recomputeUsage(orgId);
328	  const org = await orgRepo.findOrgById(orgId);
329	  if (!org) return usage;
330	
331	  const limits = getPlanLimits(org.plan);
332	
333	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
334	    await emit("billing.limit_exceeded", {
335	      orgId,
336	      actorId: null,
337	      occurredAt: toIsoTimestamp(new Date()),
338	      resource: "seats",
339	      limit: limits.seats,
340	      used: usage.seatsUsed,
341	    });
342	  }
343	
344	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
345	    await emit("billing.limit_exceeded", {
346	      orgId,
347	      actorId: null,
348	      occurredAt: toIsoTimestamp(new Date()),
349	      resource: "projects",
350	      limit: limits.projects,
351	      used: usage.projectsUsed,
352	    });
353	  }
354	
355	  return usage;
356	}
