467	/** Groups a feed page by calendar day, newest day first. */
468	export function groupByDay(
469	  events: readonly ActivityEvent[],
470	): readonly ActivityGroup[] {
471	  const byDay = new Map<string, ActivityEvent[]>();
472	
473	  for (const event of events) {
474	    const day = event.occurredAt.slice(0, 10);
475	    const bucket = byDay.get(day) ?? [];
476	    bucket.push(event);
477	    byDay.set(day, bucket);
478	  }
479	
480	  return [...byDay.entries()]
481	    .sort(([a], [b]) => (a < b ? 1 : -1))
482	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
483	}
