669	/**
670	 * Runs a query against the denormalised index. Field-scoped syntax
671	 * (`status:done`) is an `advanced_search` feature, so a query containing a
672	 * colon is rejected for plans that do not include it rather than silently
673	 * being treated as literal text.
674	 */
675	export async function search(
676	  actor: Actor,
677	  input: SearchQueryInput,
678	): Promise<Page<SearchHit>> {
679	  assertOrgScope(actor, input.orgId);
680	  assertCan(actor, "issue:read", orgResource(input.orgId));
681	
682	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
683	  if (!verdict.allowed) {
684	    throw new Error(
685	      `Search rate limit reached; try again after ${verdict.resetAt}`,
686	    );
687	  }
688	
689	  const org = await orgRepo.findOrgById(input.orgId);
690	  const advanced = isEnabled("advanced_search", {
691	    orgId: input.orgId,
692	    userId: actor.userId,
693	    plan: org?.plan ?? "free",
694	    role: actor.role,
695	    overrides: org?.settings.enabledFlagOverrides,
696	  });
697	
698	  if (input.q.includes(":") && !advanced) {
699	    throw new Error("Field-scoped search is not included in this plan");
700	  }
701	
702	  const page = await searchRepo.searchDocuments(input);
703	
704	  return {
705	    items: page.items.map((row) => ({
706	      kind: row.subjectKind,
707	      id: row.subjectId,
708	      title: row.content.split("\n")[0] ?? row.subjectId,
709	      snippet: snippetAround(row.content, input.q),
710	      href: hrefFor(row.subjectKind, row.subjectId),
711	    })),
712	    nextCursor: page.nextCursor,
713	    total: page.total,
714	  };
715	}
