814	function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
815	  switch (kind) {
816	    case "issue":
817	      return `/issues/${subjectId}`;
818	    case "comment":
819	      return `/comments/${subjectId}`;
820	    case "project":
821	      return `/projects/${subjectId}`;
