825	function snippetAround(content: string, query: string): string {
826	  const at = content.toLowerCase().indexOf(query.toLowerCase());
827	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
828	
829	  const start = Math.max(0, at - SNIPPET_RADIUS);
830	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
831	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
832	    end < content.length ? "…" : ""
833	  }`;
834	}
