1164	export function groupEventsByDay(
1165	  events: readonly ActivityEvent[],
1166	): readonly ActivityGroup[] {
1167	  const byDay = new Map<string, ActivityEvent[]>();
1168	
1169	  for (const event of events) {
1170	    const day = activityDay(event);
1171	    const bucket = byDay.get(day) ?? [];
1172	    bucket.push(event);
1173	    byDay.set(day, bucket);
1174	  }
1175	
1176	  return [...byDay.entries()]
1177	    .sort(([a], [b]) => b.localeCompare(a))
1178	    .map(([day, bucket]) => ({
1179	      day,
1180	      events: [...bucket].sort((a, b) =>
1181	        b.occurredAt.localeCompare(a.occurredAt),
1182	      ),
1183	    }));
