1185	/**
1186	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
1187	 *
1188	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
1189	 */
1190	import { subscribe } from "@/lib/event-bus";
