1202	 * attaches the notification fan-out on first import — that hub has no
1203	 * `register*` entry point of its own.
1204	 */
1205	import "./notification-service";
1206	
1207	const logger = createLogger("event-registry");
1208	
1209	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
1210	let detach: Unsubscribe | null = null;
1211	
1212	/**
1213	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
1214	 * runs per server process, but a hot reload in dev can call it again and must
1215	 * not double-deliver every event.
1216	 */
1217	export function registerEventHandlers(): void {
1218	  if (detach !== null) return;
1219	
1220	  const offs: Unsubscribe[] = [
1221	    registerActivityListeners(),
1222	    registerSearchListeners(),
1223	    registerUsageListeners(),
1224	    registerWebhookListeners(),
1225	    registerDigestBridge(),
1226	  ];
1227	
1228	  detach = () => {
1229	    for (const off of offs) off();
1230	  };
1231	
1232	  logger.info("event handlers registered", { groups: offs.length });
1233	}
1234	
1235	export function unregisterEventHandlers(): void {
1236	  detach?.();
1237	  detach = null;
1238	}
1239	
1240	/**
