1242	 * `digest.due` event into a queued job. Keeping it here rather than inside
1243	 * `DigestService` stops the service layer from depending on the job layer.
1244	 */
1245	function registerDigestBridge(): Unsubscribe {
1246	  return subscribe("digest.due", (payload) => {
1247	    enqueue({
1248	      id: `digest:${payload.orgId}:${payload.recipientId}`,
1249	      kind: "digest-email",
1250	      runAt: toIsoTimestamp(new Date()),
1251	      attempts: 0,
1252	      payload: {
1253	        orgId: payload.orgId,
1254	        recipientId: payload.recipientId,
1255	        windowStart: payload.windowStart,
1256	      },
1257	    });
1258	  });
