import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { cloneProjectSchema } from "@/schemas/project";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("clones", async () => {
  const t = await createTenant("clone", "growth");
  for (let i = 0; i < 205; i++) {
    const is = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: `Issue ${i}`, assigneeId: t.userIds.admin }));
    if (i === 3) await issueService.archiveIssue(t.actors.member, t.org.id, is.id);
    if (i === 4) await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: is.id, status: "done" });
  }
  registerEventHandlers();
  const before = await usageRepo.getUsage(t.org.id);
  const seen: unknown[] = [];
  subscribe("project.cloned", (p) => { seen.push(p); });
  const input = cloneProjectSchema.parse({ orgId: t.org.id, projectId: t.project.id, name: "Copy", slug: "platform", key: "CPY" });
  const p = await projectService.cloneProject(t.actors.member, input);
  expect(p.slug).toBe("platform-2");
  const page = await issueRepo.listIssues({ orgId: t.org.id, projectId: p.id, limit: 100, cursor: null });
  expect(page.total).toBe(204);
  const four = await issueRepo.findIssueByNumber(t.org.id, p.id, 4);
  expect(four).toMatchObject({ title: "Issue 4", status: "backlog", assigneeId: null, completedAt: null, authorId: t.userIds.member });
  expect((await issueRepo.findIssueByNumber(t.org.id, p.id, 204))?.title).toBe("Issue 204");
  const after = await usageRepo.getUsage(t.org.id);
  expect(after.projectsUsed - before.projectsUsed).toBe(1);
  expect(after.issuesUsed - before.issuesUsed).toBe(204);
  expect(await searchRepo.countIndexed(t.org.id)).toBe(205);
  const acts = await activityRepo.listActivity({ orgId: t.org.id, action: ["project.cloned"], limit: 10, cursor: null });
  expect(acts.items).toHaveLength(1);
  console.log(acts.items[0], seen);
}, 60000);
EOF
